{
  "verdicts": [
    {
      "id": 1,
      "label": "supported",
      "paper_evidence": "We present ALBIREO, a detector-agnostic, codec-free, adaptive inference framework that wraps off-the-shelf object detectors and decides when detector invocation can be safely skipped based on scene content and per-object temporal state.",
      "reason": "Section I explicitly describes ALBIREO as detector-agnostic and skipping based on scene content and object state."
    },
    {
      "id": 2,
      "label": "supported",
      "paper_evidence": "On the primary YOLO26x configuration, ALBIREO improves AP@50 by +0.8 pp while reducing energy by 17.6% on Thor.",
      "reason": "Section IV-B and Table III confirm the +0.8 pp AP@50 improvement and 17.6% energy reduction on Thor for YOLO26x."
    },
    {
      "id": 3,
      "label": "supported",
      "paper_evidence": "Running YOLO26x on every frame draws 70 W of total board power on Jetson AGX Thor (Blackwell, 130 W TDP), of which 34 W (49%) is the GPU power.",
      "reason": "Section I and Section IV-G explicitly state that per-frame detector invocation draws 70 W on Jetson AGX Thor."
    },
    {
      "id": 4,
      "label": "supported",
      "paper_evidence": "Sweeping the primary uncertainty threshold on YOLO26x traces an AP@50–EDP Pareto frontier that dominates the evaluated frame-skipping baselines (FixedSkip-N, CTD, Statues) within the target operating region (AP@50 ≥ 0.50).",
      "reason": "Section IV-B and Figure 2 confirm that ALBIREO's threshold sweep forms the upper Pareto frontier in the AP@50 ≥ 0.50 region on both platforms."
    },
    {
      "id": 5,
      "label": "supported",
      "paper_evidence": "Across all evaluated detectors and platforms, ALBIREO keeps AP@50 within 1.2 pp of Vanilla per-frame inference while reducing energy by 12.1–17.6%.",
      "reason": "Section I and Table IV confirm the energy reduction range and AP@50 consistency across detectors and platforms."
    },
    {
      "id": 6,
      "label": "supported",
      "paper_evidence": "Figure 7 highlights the two operating modes on representative clips. On a dense urban clip (no empty frames; 96% AI rate), ALBIREO and Vanilla draw similar power because the detector runs on most frames; rescue primarily preserves AP@50 rather than reducing energy. On a sparse highway clip (69% E, 4% AI), ALBIREO’s GPU power drops sharply during long ERD-only stretches, while Vanilla continues running full detector inference.",
      "reason": "Figure 7 explicitly shows per-clip power traces for two representative BDD100K clips on Thor with YOLO26x."
    },
    {
      "id": 7,
      "label": "supported",
      "paper_evidence": "On a dense urban clip (no empty frames; 96% AI rate), ALBIREO and Vanilla draw similar power because the detector runs on most frames; rescue primarily preserves AP@50 rather than reducing energy.",
      "reason": "Figure 7 and Section IV-H describe dense urban traffic with 0% E and 96% AI, where rescue preserves AP@50."
    },
    {
      "id": 8,
      "label": "supported",
      "paper_evidence": "On a sparse highway clip (69% E, 4% AI), ALBIREO’s GPU power drops sharply during long ERD-only stretches, while Vanilla continues running full detector inference.",
      "reason": "Figure 7 and Section IV-H describe sparse highway scenes with 69% E and 4% AI, where GPU power drops during ERD-only stretches."
    },
    {
      "id": 9,
      "label": "supported",
      "paper_evidence": "Figure 1 illustrates how execution moves between these states across consecutive frames as scenes become empty or non-empty, uncertainty triggers fire, detections match, or rescue is needed.",
      "reason": "Figure 1 explicitly shows frame-state transitions across consecutive frames, with edges representing events."
    },
    {
      "id": 10,
      "label": "supported",
      "paper_evidence": "AI follows the same next-frame routing as I; self-loops are omitted.",
      "reason": "Section III-D and Figure 1 confirm that AI follows the same next-frame routing as I, with self-loops omitted."
    },
    {
      "id": 11,
      "label": "supported",
      "paper_evidence": "Table IV evaluates ALBIREO’s detector-agnostic design across three off-the-shelf detectors and two Jetson platforms. Across the evaluated detectors, AP@50 remains within ±1.2 pp of Vanilla while energy savings range from 12.1% on RF-DETR-Large/Orin to 17.6% on YOLO26x/Thor.",
      "reason": "Table IV explicitly shows default ALBIREO relative to Vanilla across detectors and platforms, averaged over 200 BDD100K MOT validation clips."
    }
  ]
}
